class CandidateRegisterScreen extends StatefulWidget { const CandidateRegisterScreen({super.key}); @override State<CandidateRegisterScreen> createState() => _CandidateRegisterState(); }
class _CandidateRegisterState extends State<CandidateRegisterScreen> {
  final n=TextEditingController(), e=TextEditingController(), phone=TextEditingController(), pw=TextEditingController(), con=TextEditingController(); bool loading=false;
  Future<void> register() async {
    final cv=con.text.trim();
    if(n.text.trim().isEmpty || e.text.trim().isEmpty || pw.text.length<8 || !RegExp(r'^[A-Za-z0-9-]{5,30}$').hasMatch(cv)){ msg(context,'Completa los campos y coloca un número de CONADIS válido.'); return; }
    setState(()=>loading=true);
    try { final r=await ApiService().registerCandidate(name:n.text.trim(),email:e.text.trim(),phone:phone.text.trim(),password:pw.text,conadisNumber:cv); await saveSession(r,'candidate'); if(mounted) replace(context,const CandidateHome()); }
    catch(x){ if(mounted) msg(context,x.toString().replaceFirst('Exception: ','')); }
    finally { if(mounted) setState(()=>loading=false); }
  }
  @override Widget build(BuildContext context)=>Page(title:'Crear cuenta de candidato',child:ListView(children:[
    const Progress('Registro','1 de 3'),
    FieldBox('Nombre completo',n), FieldBox('Correo electrónico',e,type:TextInputType.emailAddress), FieldBox('Teléfono',phone,type:TextInputType.phone), FieldBox('Contraseña',pw,obscure:true),
    const Text('Número de CONADIS *',style:TextStyle(fontWeight:FontWeight.w700)), const SizedBox(height:7),
    TextField(controller:con,textCapitalization:TextCapitalization.characters,decoration:const InputDecoration(hintText:'Ingresa tu número de CONADIS')),
    const SizedBox(height:7), const Text('Obligatorio y único para cada candidato.',style:TextStyle(fontSize:12,color:Colors.black54)), const SizedBox(height:22),
    PrimaryButton(loading?'Registrando...':'Continuar',loading?null:register),
  ]));
}

class CompanyRegisterScreen extends StatefulWidget { const CompanyRegisterScreen({super.key}); @override State<CompanyRegisterScreen> createState()=>_CompanyRegisterState(); }
class _CompanyRegisterState extends State<CompanyRegisterScreen>{
  final n=TextEditingController(),e=TextEditingController(),phone=TextEditingController(),ruc=TextEditingController(),pw=TextEditingController(); bool loading=false;
  Future<void> register() async { if(n.text.trim().isEmpty||e.text.trim().isEmpty||pw.text.length<8||ruc.text.trim().length<8){msg(context,'Completa los datos de la empresa.');return;} setState(()=>loading=true); try{final r=await ApiService().registerCompany(name:n.text.trim(),email:e.text.trim(),phone:phone.text.trim(),password:pw.text,ruc:ruc.text.trim());await saveSession(r,'company');if(mounted)replace(context,const CompanyHome());}catch(x){if(mounted)msg(context,x.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(()=>loading=false);}}
  @override Widget build(BuildContext context)=>Page(title:'Crear cuenta de empresa',child:ListView(children:[const Progress('Registro','1 de 3'),FieldBox('Nombre de empresa',n),FieldBox('Correo empresarial',e,type:TextInputType.emailAddress),FieldBox('Teléfono',phone,type:TextInputType.phone),FieldBox('RUC',ruc,type:TextInputType.number),FieldBox('Contraseña',pw,obscure:true),const SizedBox(height:22),PrimaryButton(loading?'Registrando...':'Continuar',loading?null:register)]));
}

class LoginScreen extends StatefulWidget { const LoginScreen({super.key}); @override State<LoginScreen> createState()=>_LoginState(); }
class _LoginState extends State<LoginScreen>{final e=TextEditingController(),pw=TextEditingController();bool loading=false;Future<void> login()async{if(e.text.trim().isEmpty||pw.text.isEmpty){msg(context,'Ingresa correo y contraseña.');return;}setState(()=>loading=true);try{final r=await ApiService().login(e.text.trim(),pw.text);final role=r['user']?['role']??'candidate';await saveSession(r,role);if(mounted)replace(context,role=='company'?const CompanyHome():const CandidateHome());}catch(x){if(mounted)msg(context,x.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext context)=>Page(title:'Iniciar sesión',child:ListView(children:[FieldBox('Correo electrónico',e,type:TextInputType.emailAddress),FieldBox('Contraseña',pw,obscure:true),const SizedBox(height:10),PrimaryButton(loading?'Ingresando...':'Iniciar sesión',loading?null:login)]));}

