class RoleCard extends StatelessWidget{final IconData icon;final String title,subtitle;final VoidCallback onTap;const RoleCard(this.icon,this.title,this.subtitle,this.onTap,{super.key});@override Widget build(BuildContext context)=>Card(child:InkWell(onTap:onTap,borderRadius:BorderRadius.circular(18),child:Padding(padding:const EdgeInsets.all(20),child:Row(children:[CircleAvatar(radius:26,backgroundColor:const Color(0xFFEDE9FE),child:Icon(icon,color:purple)),const SizedBox(width:16),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontSize:18,fontWeight:FontWeight.w800)),const SizedBox(height:4),Text(subtitle,style:const TextStyle(color:Colors.black54))])),const Icon(Icons.chevron_right)]))));}
class JobCard extends StatelessWidget{final dynamic job;final VoidCallback onTap;const JobCard({super.key,required this.job,required this.onTap});@override Widget build(BuildContext context)=>Card(margin:const EdgeInsets.only(bottom:12),child:ListTile(onTap:onTap,contentPadding:const EdgeInsets.all(14),leading:const CircleAvatar(backgroundColor:Color(0xFFEDE9FE),child:Icon(Icons.work_outline,color:purple)),title:Text(job['title']??'Oferta laboral',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${job['companyId'] is Map?(job['companyId']['name']??'Empresa'):'Empresa'}\n${job['modality']??'Modalidad por definir'}'),isThreeLine:true,trailing:const Icon(Icons.chevron_right)));}
class Tag extends StatelessWidget{final String text;const Tag(this.text,{super.key});@override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.symmetric(horizontal:10,vertical:6),decoration:BoxDecoration(color:const Color(0xFFEDE9FE),borderRadius:BorderRadius.circular(20)),child:Text(text,style:const TextStyle(fontSize:12,color:purple,fontWeight:FontWeight.w700)));}
class Stat extends StatelessWidget{final String value,label;const Stat(this.value,this.label,{super.key});@override Widget build(BuildContext context)=>Column(children:[Text(value,style:const TextStyle(fontSize:24,fontWeight:FontWeight.w800,color:purple)),Text(label,textAlign:TextAlign.center,style:const TextStyle(fontSize:11,color:Colors.black54))]);}
class Empty extends StatelessWidget{final String text;const Empty(this.text,{super.key});@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.symmetric(vertical:35),child:Center(child:Text(text,textAlign:TextAlign.center,style:const TextStyle(color:Colors.black54))));}
void push(BuildContext c,Widget w)=>Navigator.push(c,MaterialPageRoute(builder:(_)=>w));
void replace(BuildContext c,Widget w)=>Navigator.pushAndRemoveUntil(c,MaterialPageRoute(builder:(_)=>w),(_)=>false);
void msg(BuildContext c,String s)=>ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(s)));
Future<void>saveSession(Map<String,dynamic>r,String role)async{final p=await SharedPreferences.getInstance();await p.setString('inklu_token',r['token']??'');await p.setString('inklu_role',role);}
